// ---------------------------------------------------------------------------
// Процедурная кампания: уровень детерминированно генерируется по индексу.
// Задания: обязательное слово (сидится на поле) + 2–4 из пула типов; сложность
// растёт с индексом (цель, лёд, ходы).
// ---------------------------------------------------------------------------
WordFallLevels = {
    _byLen: null,

    _EnsureIndex: function()
    {
        if (this._byLen)
            return;
        this._byLen = {};
        for (var i = 0; i < WordDict.length; i++)
        {
            var w = WordDict[i];
            if (!this._byLen[w.length])
                this._byLen[w.length] = [];
            this._byLen[w.length].push(w);
        }
    },

    Get: function(index)
    {
        this._EnsureIndex();

        var seed = (977 + index*7919) >>> 0;
        var rand = function() { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296; };
        var randInt = function(n) { return Math.floor(rand() * n); };
        var byLen = this._byLen;
        // слова-задания из частых букв (низкие номиналы) — обычно обиходные
        var pickWord = function(len)
        {
            var bucket = byLen[len];
            for (var attempt = 0; attempt < 30; attempt++)
            {
                var w = bucket[randInt(bucket.length)];
                var rare = false;
                for (var i = 0; i < w.length; i++)
                {
                    if ((WordFallConfig.letterValues[w[i]] || 5) > 3)
                        rare = true;
                }
                if (!rare)
                    return w;
            }
            return bucket[randInt(bucket.length)];
        };

        var tier = Math.floor(index / 10);                        // 0..9
        var moves = 12 + Math.min(4, Math.floor(index / 25));     // 12..16
        var target = 250 + tier*50 + randInt(30);                 // рампа, калибровано ботом
        var iceCount = Math.min(3 + Math.floor(index / 12), 10);

        var ice = [];
        var usedCells = {};
        var guard = 0;
        while (ice.length < iceCount && guard++ < 300)
        {
            var c = randInt(WordFallConfig.cols);
            var r = randInt(WordFallConfig.rows);
            var key = c + "_" + r;
            if (usedCells[key])
                continue;
            usedCells[key] = true;
            ice.push([c, r]);
        }

        // обязательное слово-задание (оно же сидится на поле)
        var tasks = [{ type: "word", word: pickWord(3 + randInt(3)) }];

        var pool = ["length", "anyWords", "wordScore", "powerup", "clearIce", "word2"];
        for (var i = pool.length - 1; i > 0; i--)
        {
            var j = randInt(i + 1);
            var tmp = pool[i]; pool[i] = pool[j]; pool[j] = tmp;
        }

        var extraCount = 2 + randInt(Math.min(3, 1 + Math.floor(index / 15)));
        for (var i = 0; i < extraCount && i < pool.length; i++)
        {
            var kind = pool[i];
            if (kind == "length")
                tasks.push({ type: "length", len: 4 + randInt(2), count: 1 + randInt(2) });
            else if (kind == "anyWords")
                tasks.push({ type: "anyWords", count: 4 + randInt(4) });
            else if (kind == "wordScore")
                tasks.push({ type: "wordScore", score: 18 + tier*2 + randInt(8) });
            else if (kind == "powerup")
            {
                var kinds = index < 10 ? ["bomb"] : index < 25 ? ["bomb", "rocket"] : ["bomb", "rocket", "wand"];
                tasks.push({ type: "powerup", kind: kinds[randInt(kinds.length)], count: 1 });
            }
            else if (kind == "clearIce")
                tasks.push({ type: "clearIce" });
            else
                tasks.push({ type: "word", word: pickWord(4 + randInt(2)) });
        }

        // «разбить весь лёд» при 8–10 льдинах невыполнимо за лимит ходов —
        // с этой задачей льда не больше шести
        if (tasks.some(function(t) { return t.type == "clearIce"; }) && ice.length > 6)
            ice.length = 6;

        return { target: target, moves: moves, ice: ice, charges: [3, 3, 30, 3, 3], tasks: tasks };
    }
};

// ---------------------------------------------------------------------------
// Чистая логика игры: сетка, мешок, выбор, очки, гравитация, бустеры.
// Не трогает движок — тестируется headless.
// ---------------------------------------------------------------------------
WordModel = class WordModel
{
    constructor(seed)
    {
        this._seed = (seed === undefined || seed === null) ? 12345 : (seed >>> 0);
        if (this._seed == 0)
            this._seed = 1;

        this._cols = WordFallConfig.cols;
        this._rows = WordFallConfig.rows;
        this._grid = null;
        this._bag = [];
        this._selected = [];
        this._score = 0;
        this._movesLeft = 0;
        this._target = 0;
        this._charges = [0, 0, 0, 0, 0];
        this._state = "playing";
        this._tasks = [];
        this._seededCells = [];

        this._dictByLen = {};
        for (var i = 0; i < WordDict.length; i++)
        {
            var w = WordDict[i];
            if (!this._dictByLen[w.length])
                this._dictByLen[w.length] = [];
            this._dictByLen[w.length].push(w);
        }
    }

    // --- RNG (детерминированный, для тестов) ---

    _Rand()
    {
        this._seed = (Math.imul(this._seed, 1664525) + 1013904223) >>> 0;
        return this._seed / 4294967296;
    }

    _RandInt(n) { return Math.floor(this._Rand() * n); }

    // --- мешок ---

    _RefillBag()
    {
        this._bag = [];
        for (var letter in WordFallConfig.bag)
        {
            for (var i = 0; i < WordFallConfig.bag[letter]; i++)
                this._bag.push(letter);
        }
    }

    IsVowel(letter) { return WordFallConfig.vowels.indexOf(letter) >= 0; }

    // Тянет букву из мешка; при forceVowel пытается взять гласную
    _DrawLetter(forceVowel)
    {
        if (this._bag.length == 0)
            this._RefillBag();

        var idx = this._RandInt(this._bag.length);
        if (forceVowel && !this.IsVowel(this._bag[idx]))
        {
            var vowelIdxs = [];
            for (var i = 0; i < this._bag.length; i++)
            {
                if (this.IsVowel(this._bag[i]))
                    vowelIdxs.push(i);
            }
            if (vowelIdxs.length > 0)
                idx = vowelIdxs[this._RandInt(vowelIdxs.length)];
        }

        var letter = this._bag[idx];
        this._bag.splice(idx, 1);
        return letter;
    }

    // Анти-клин под механику цепочек: слова собираются по соседям, поэтому у
    // каждой буквы должна быть гласная в 8-соседстве. Если среди уже заполненных
    // соседей клетки спавна две и более букв и ни одной гласной — спавним гласную.
    _NeedVowelAt(column, row)
    {
        var filled = 0;
        var vowels = 0;
        for (var dc = -1; dc <= 1; dc++)
        {
            for (var dr = -1; dr <= 1; dr++)
            {
                if (dc == 0 && dr == 0)
                    continue;
                var c = column + dc;
                var r = row + dr;
                if (c < 0 || c >= this._cols || r < 0 || r >= this._rows)
                    continue;
                var tile = this._grid[c] ? this._grid[c][r] : null;
                if (!tile)
                    continue;
                filled++;
                if (this.IsVowel(tile.letter) || tile.joker)
                    vowels++;
            }
        }
        return filled >= 2 && vowels == 0;
    }

    _MakeTile(letter)
    {
        return { letter: letter, value: WordFallConfig.letterValues[letter], ice: 0,
                 doubled: false, joker: false, powerup: null };
    }

    // --- уровень ---

    NewGame(level)
    {
        level = level || WordFallConfig.level;
        this._target = level.target;
        this._movesLeft = level.moves;
        this._charges = level.charges.slice();
        this._score = 0;
        this._state = "playing";
        this._selected = [];
        this._RefillBag();

        this._grid = [];
        for (var c = 0; c < this._cols; c++)
        {
            this._grid[c] = [];
            for (var r = 0; r < this._rows; r++)
                this._grid[c][r] = this._MakeTile(this._DrawLetter(this._NeedVowelAt(c, r)));
        }

        this._InitTasks(level);

        // одно из слов заданий обязано оказаться на поле — игроку проще начать
        this._seededCells = [];
        var wordTasks = this._tasks.filter(function(t) { return t.type == "word"; });
        if (wordTasks.length > 0)
            this._SeedWord(wordTasks[this._RandInt(wordTasks.length)].word);

        for (var i = 0; i < level.ice.length; i++)
        {
            var cell = level.ice[i];
            var seeded = this._seededCells.some(function(s) { return s.c == cell[0] && s.r == cell[1]; });
            if (!seeded)
                this._grid[cell[0]][cell[1]].ice = 1;
        }

        this._RefreshIceTasks();
        this._EnsureTasksAchievable();
    }

    // Выкладывает слово горизонтально в случайном месте поля
    _SeedWord(word)
    {
        var maxStartColumn = this._cols - word.length;
        if (maxStartColumn < 0)
            return;

        var c0 = this._RandInt(maxStartColumn + 1);
        var r = 2 + this._RandInt(4); // средние ряды — слово видно сразу
        for (var i = 0; i < word.length; i++)
        {
            this._grid[c0 + i][r] = this._MakeTile(word[i]);
            this._seededCells.push({ c: c0 + i, r: r });
        }
    }

    // --- задания уровня ---

    _InitTasks(level)
    {
        this._tasks = [];
        var specs = level.tasks || [];
        for (var i = 0; i < specs.length; i++)
        {
            var spec = specs[i];
            var task = { type: spec.type, count: spec.count || 1, progress: 0, done: false };
            if (spec.type == "word")
                task.word = spec.word;
            else if (spec.type == "length")
                task.len = spec.len;
            else if (spec.type == "powerup")
                task.kind = spec.kind;
            else if (spec.type == "wordScore")
                task.score = spec.score;
            this._tasks.push(task);
        }
    }

    GetTasks() { return this._tasks; }
    GetSeededCells() { return this._seededCells; }

    _TasksDone() { return this._tasks.every(function(t) { return t.done; }); }

    _BumpTask(task)
    {
        task.progress++;
        if (task.progress >= task.count)
            task.done = true;
    }

    _UpdateTasksAfterWord(pattern, wordTotal)
    {
        for (var i = 0; i < this._tasks.length; i++)
        {
            var t = this._tasks[i];
            if (t.done)
                continue;

            if (t.type == "word" && this._MatchWord(pattern, t.word))
                this._BumpTask(t);
            else if (t.type == "length" && pattern.length == t.len)
                this._BumpTask(t);
            else if (t.type == "anyWords")
                this._BumpTask(t);
            else if (t.type == "wordScore" && wordTotal >= t.score)
                this._BumpTask(t);
        }
    }

    _OnPowerupEarned(kind)
    {
        for (var i = 0; i < this._tasks.length; i++)
        {
            var t = this._tasks[i];
            if (!t.done && t.type == "powerup" && (t.kind == kind || t.kind == "any"))
                this._BumpTask(t);
        }
    }

    _RefreshIceTasks()
    {
        var ice = 0;
        for (var c = 0; c < this._cols; c++)
        {
            for (var r = 0; r < this._rows; r++)
            {
                if (this._grid[c][r] && this._grid[c][r].ice > 0)
                    ice++;
            }
        }

        if (ice > 0)
            return;

        for (var i = 0; i < this._tasks.length; i++)
        {
            if (this._tasks[i].type == "clearIce")
                this._tasks[i].done = true;
        }
    }

    // Очки — обязательное финальное условие: победа только с закрытыми задачами
    _CheckWin()
    {
        if (this._state == "playing" && this._score >= this._target && this._TasksDone())
            this._state = "win";
    }

    // --- доступ к состоянию ---

    GetTile(c, r) { return this._grid[c][r]; }
    GetScore() { return this._score; }
    GetTarget() { return this._target; }
    GetMovesLeft() { return this._movesLeft; }
    GetState() { return this._state; }
    GetCharges(i) { return this._charges[i]; }
    GetSelected() { return this._selected; }

    // --- выбор букв: свободный по всему полю ---

    ToggleSelect(c, r)
    {
        if (this._state != "playing")
            return "blocked";

        var tile = this._grid[c][r];
        if (tile.ice > 0)
            return "ice";

        for (var i = 0; i < this._selected.length; i++)
        {
            if (this._selected[i].c == c && this._selected[i].r == r)
            {
                this._selected.length = i; // снять эту букву и весь хвост после неё
                return "removed";
            }
        }

        this._selected.push({ c: c, r: r });
        return "added";
    }

    ClearSelection() { this._selected = []; }

    CurrentWord()
    {
        var word = "";
        for (var i = 0; i < this._selected.length; i++)
        {
            var tile = this._grid[this._selected[i].c][this._selected[i].r];
            word += tile.joker ? "?" : tile.letter;
        }
        return word;
    }

    // --- словарь (джокер «?» матчится с любой буквой) ---

    _MatchWord(pattern, word)
    {
        if (pattern.length != word.length)
            return false;

        for (var i = 0; i < pattern.length; i++)
        {
            if (pattern[i] != "?" && pattern[i] != word[i])
                return false;
        }
        return true;
    }

    IsWordInDict(pattern)
    {
        if (pattern.length < 2)
            return false;

        var words = this._dictByLen[pattern.length];
        if (!words)
            return false;

        if (pattern.indexOf("?") < 0)
            return words.indexOf(pattern) >= 0;

        for (var i = 0; i < words.length; i++)
        {
            if (this._MatchWord(pattern, words[i]))
                return true;
        }
        return false;
    }

    // --- очки ---

    // Размер максимальной связной компоненты выбранных плиток (8-соседство):
    // бонус за компактность при свободном выборе
    ClusterSize(cells)
    {
        if (cells.length == 0)
            return 0;

        var visited = [];
        var best = 1;
        for (var i = 0; i < cells.length; i++)
        {
            if (visited.indexOf(i) >= 0)
                continue;

            var queue = [i];
            visited.push(i);
            var size = 0;
            while (queue.length > 0)
            {
                var cur = cells[queue.pop()];
                size++;
                for (var j = 0; j < cells.length; j++)
                {
                    if (visited.indexOf(j) >= 0)
                        continue;

                    var dc = Math.abs(cells[j].c - cur.c);
                    var dr = Math.abs(cells[j].r - cur.r);
                    if (dc <= 1 && dr <= 1)
                    {
                        visited.push(j);
                        queue.push(j);
                    }
                }
            }
            best = Math.max(best, size);
        }
        return best;
    }

    LengthMultiplier(length) { return length > 3 ? 1 + 0.25*(length - 3) : 1; }

    ComputeScore(cells)
    {
        var base = 0;
        for (var i = 0; i < cells.length; i++)
        {
            var tile = this._grid[cells[i].c][cells[i].r];
            if (!tile.joker)
                base += tile.value * (tile.doubled ? 2 : 1);
        }

        var cluster = this.ClusterSize(cells);
        var clusterMult = cluster >= 2 ? cluster : 1;
        var lenMult = this.LengthMultiplier(cells.length);
        return {
            base: base,
            lenMult: lenMult,
            cluster: clusterMult,
            total: Math.ceil(base * lenMult * clusterMult)
        };
    }

    // --- пауэрапы за длинные слова ---

    PowerupForLength(length)
    {
        var lens = WordFallConfig.powerupLengths;
        if (length >= lens.wand)
            return "wand";
        if (length >= lens.rocket)
            return "rocket";
        if (length >= lens.bomb)
            return "bomb";
        return null;
    }

    _CellKey(c, r) { return c + "_" + r; }

    _TileValue(tile) { return tile.joker ? 0 : tile.value * (tile.doubled ? 2 : 1); }

    // Плитка активируется: очки в счёт, лёд снят, сама остаётся на поле
    _ActivateTile(c, r, destroyedKeys, result)
    {
        if (destroyedKeys[this._CellKey(c, r)])
            return;
        if (result.activated.some(function(a) { return a.c == c && a.r == r; }))
            return;

        var tile = this._grid[c][r];
        result.extra += this._TileValue(tile);
        if (tile.ice > 0)
        {
            tile.ice = 0;
            result.iceBroken.push({ c: c, r: r });
        }
        result.activated.push({ c: c, r: r });
    }

    // Срабатывание пауэрапов на плитках собранного слова: бомба уничтожает 3×3
    // (очки взорванных букв — в счёт), ракета крестом и палочка по одинаковым
    // буквам активируют плитки, не убирая их с поля
    _ActivatePowerups(cells)
    {
        var destroyedKeys = {};
        for (var i = 0; i < cells.length; i++)
            destroyedKeys[this._CellKey(cells[i].c, cells[i].r)] = true;

        var result = { extra: 0, destroyed: [], activated: [], iceBroken: [], used: [],
                       destroyedKeys: destroyedKeys };

        for (var i = 0; i < cells.length; i++)
        {
            var c = cells[i].c, r = cells[i].r;
            var kind = this._grid[c][r].powerup;
            if (!kind)
                continue;

            result.used.push({ kind: kind, c: c, r: r });

            if (kind == "bomb")
            {
                for (var dc = -1; dc <= 1; dc++)
                {
                    for (var dr = -1; dr <= 1; dr++)
                    {
                        var cc = c + dc, rr = r + dr;
                        if (cc < 0 || cc >= this._cols || rr < 0 || rr >= this._rows)
                            continue;

                        var key = this._CellKey(cc, rr);
                        if (destroyedKeys[key])
                            continue;

                        destroyedKeys[key] = true;
                        var tile = this._grid[cc][rr];
                        result.extra += this._TileValue(tile);
                        if (tile.ice > 0)
                            result.iceBroken.push({ c: cc, r: rr });
                        result.destroyed.push({ c: cc, r: rr });
                    }
                }
            }
            else if (kind == "rocket")
            {
                for (var cc = 0; cc < this._cols; cc++)
                    this._ActivateTile(cc, r, destroyedKeys, result);
                for (var rr = 0; rr < this._rows; rr++)
                    this._ActivateTile(c, rr, destroyedKeys, result);
            }
            else if (kind == "wand")
            {
                var letter = this._grid[c][r].letter;
                for (var cc = 0; cc < this._cols; cc++)
                {
                    for (var rr = 0; rr < this._rows; rr++)
                    {
                        if (this._grid[cc][rr].letter == letter && !this._grid[cc][rr].joker)
                            this._ActivateTile(cc, rr, destroyedKeys, result);
                    }
                }
            }
        }
        return result;
    }

    // --- сжигание, лёд, гравитация, спавн ---

    _DamageIceAround(cells, skipKeys)
    {
        var broken = [];
        for (var i = 0; i < cells.length; i++)
        {
            for (var dc = -1; dc <= 1; dc++)
            {
                for (var dr = -1; dr <= 1; dr++)
                {
                    var c = cells[i].c + dc;
                    var r = cells[i].r + dr;
                    if (c < 0 || c >= this._cols || r < 0 || r >= this._rows)
                        continue;
                    if (skipKeys && skipKeys[this._CellKey(c, r)])
                        continue;

                    var tile = this._grid[c][r];
                    if (tile && tile.ice > 0 && !broken.some(function(b) { return b.c == c && b.r == r; }))
                    {
                        tile.ice--;
                        if (tile.ice == 0)
                            broken.push({ c: c, r: r });
                    }
                }
            }
        }
        return broken;
    }

    // Удаляет плитки cells, роняет столбцы, спавнит новые. Возвращает анимационные списки.
    _CollapseAndSpawn(cells)
    {
        for (var i = 0; i < cells.length; i++)
            this._grid[cells[i].c][cells[i].r] = null;

        var moved = [];
        var spawned = [];
        for (var c = 0; c < this._cols; c++)
        {
            var stack = [];
            for (var r = 0; r < this._rows; r++)
            {
                if (this._grid[c][r])
                    stack.push({ tile: this._grid[c][r], fromR: r });
            }

            for (var r = 0; r < this._rows; r++)
            {
                if (r < stack.length)
                {
                    this._grid[c][r] = stack[r].tile;
                    if (stack[r].fromR != r)
                        moved.push({ c: c, fromR: stack[r].fromR, toR: r });
                }
                else
                {
                    this._grid[c][r] = this._MakeTile(this._DrawLetter(this._NeedVowelAt(c, r)));
                    spawned.push({ c: c, r: r, letter: this._grid[c][r].letter });
                }
            }
        }
        return { moved: moved, spawned: spawned };
    }

    AcceptWord()
    {
        if (this._state != "playing")
            return { ok: false, reason: "blocked" };

        var word = this.CurrentWord();
        if (!this.IsWordInDict(word))
            return { ok: false, reason: "invalid", word: word };

        var cells = this._selected.slice();
        var score = this.ComputeScore(cells);
        var powerups = this._ActivatePowerups(cells);
        var gain = score.total + powerups.extra;
        this._score += gain;

        var iceBroken = this._DamageIceAround(cells, powerups.destroyedKeys).concat(powerups.iceBroken);
        var collapse = this._CollapseAndSpawn(cells.concat(powerups.destroyed));

        // длинное слово — пауэрап прикрепляется к плитке, занявшей клетку последней буквы
        var earned = this.PowerupForLength(cells.length);
        if (earned)
        {
            var last = cells[cells.length - 1];
            this._grid[last.c][last.r].powerup = earned;
            this._OnPowerupEarned(earned);
        }

        this._UpdateTasksAfterWord(word, score.total);
        this._RefreshIceTasks();

        this._movesLeft--;
        this._selected = [];

        this._CheckWin();
        if (this._state == "playing" && this._movesLeft <= 0)
            this._state = "lose";

        // страховка выполнимости: если продолжаем играть — каждое незакрытое
        // задание должно быть достижимо, иначе подсеваются недостающие буквы
        var repaired = this._EnsureTasksAchievable();

        return {
            ok: true, word: word, score: score, gain: gain, burned: cells,
            powerupsUsed: powerups.used, activated: powerups.activated, powerupEarned: earned,
            iceBroken: iceBroken, repaired: repaired,
            moved: collapse.moved, spawned: collapse.spawned, state: this._state
        };
    }

    // --- бустеры ---

    // Молоток: сносит любую плитку (и лёд) без траты хода
    UseHammer(c, r)
    {
        if (this._state != "playing" || this._charges[0] <= 0)
            return { ok: false };

        this._charges[0]--;
        this._selected = [];
        var collapse = this._CollapseAndSpawn([{ c: c, r: r }]);

        // молоток мог снести последний лёд — задача закрывается и без хода
        this._RefreshIceTasks();
        this._CheckWin();
        this._EnsureTasksAchievable();

        return { ok: true, moved: collapse.moved, spawned: collapse.spawned };
    }

    // Перемешивание: перетасовка букв по не-ледяным клеткам
    UseShuffle()
    {
        if (this._state != "playing" || this._charges[1] <= 0)
            return { ok: false };

        this._charges[1]--;
        this._selected = [];

        var cells = [];
        for (var c = 0; c < this._cols; c++)
        {
            for (var r = 0; r < this._rows; r++)
            {
                if (this._grid[c][r].ice == 0)
                    cells.push({ c: c, r: r });
            }
        }

        var tiles = cells.map(function(cell) { return this._grid[cell.c][cell.r]; }, this);
        for (var i = tiles.length - 1; i > 0; i--)
        {
            var j = this._RandInt(i + 1);
            var tmp = tiles[i]; tiles[i] = tiles[j]; tiles[j] = tmp;
        }
        for (var i = 0; i < cells.length; i++)
            this._grid[cells[i].c][cells[i].r] = tiles[i];

        this._EnsureTasksAchievable();
        return { ok: true };
    }

    // --- выполнимость заданий: после каждого изменения поля проверяем, что каждое
    // незакрытое задание можно продвинуть; если нет — подсеваем недостающие буквы
    // (замена случайных плиток без льда и пауэрапов) ---

    _CanAssembleWord(word)
    {
        var counts = {};
        var jokers = 0;
        for (var c = 0; c < this._cols; c++)
        {
            for (var r = 0; r < this._rows; r++)
            {
                var tile = this._grid[c][r];
                if (tile.ice > 0)
                    continue;
                if (tile.joker)
                    jokers++;
                else
                    counts[tile.letter] = (counts[tile.letter] || 0) + 1;
            }
        }

        var need = {};
        var deficit = 0;
        for (var i = 0; i < word.length; i++)
        {
            var ch = word[i];
            need[ch] = (need[ch] || 0) + 1;
            if (need[ch] > (counts[ch] || 0))
                deficit++;
        }
        return deficit <= jokers;
    }

    _RandomDictWord(length)
    {
        var bucket = this._dictByLen[length];
        return bucket ? bucket[this._RandInt(bucket.length)] : null;
    }

    // дорогое слово для ремонта wordScore-задачи: максимум базы по случайной выборке
    _ExpensiveDictWord()
    {
        var bucket = this._dictByLen[7] || this._dictByLen[6];
        var best = null;
        var bestBase = -1;
        for (var i = 0; i < 40; i++)
        {
            var word = bucket[this._RandInt(bucket.length)];
            var base = 0;
            for (var li = 0; li < word.length; li++)
                base += WordFallConfig.letterValues[word[li]] || 0;
            if (base > bestBase)
            {
                bestBase = base;
                best = word;
            }
        }
        return best;
    }

    _PickRepairCell(repaired)
    {
        for (var attempt = 0; attempt < 60; attempt++)
        {
            var c = this._RandInt(this._cols);
            var r = this._RandInt(this._rows);
            var tile = this._grid[c][r];
            if (tile.ice > 0 || tile.powerup)
                continue;
            var taken = repaired.some(function(cell) { return cell.c == c && cell.r == r; });
            if (!taken)
                return { c: c, r: r };
        }
        return null;
    }

    // Подсев недостающих для слова букв (джокеры не в счёт — сеем реальные буквы)
    _PlantMissingLetters(word, repaired)
    {
        if (!word)
            return;

        var counts = {};
        for (var c = 0; c < this._cols; c++)
        {
            for (var r = 0; r < this._rows; r++)
            {
                var tile = this._grid[c][r];
                if (tile.ice == 0 && !tile.joker)
                    counts[tile.letter] = (counts[tile.letter] || 0) + 1;
            }
        }

        var need = {};
        for (var i = 0; i < word.length; i++)
            need[word[i]] = (need[word[i]] || 0) + 1;

        for (var ch in need)
        {
            var lack = need[ch] - (counts[ch] || 0);
            for (var k = 0; k < lack; k++)
            {
                var cell = this._PickRepairCell(repaired);
                if (!cell)
                    return;
                this._grid[cell.c][cell.r] = this._MakeTile(ch);
                repaired.push(cell);
            }
        }
    }

    // Существует ли собираемое слово (опц. точной длины): при свободном выборе
    // счётчики букв — точный критерий, первый прошедший префильтр = да
    _AnyWordExists(requiredLen)
    {
        var counts = {};
        var jokers = 0;
        for (var c = 0; c < this._cols; c++)
        {
            for (var r = 0; r < this._rows; r++)
            {
                var tile = this._grid[c][r];
                if (tile.ice > 0)
                    continue;
                if (tile.joker)
                    jokers++;
                else
                    counts[tile.letter] = (counts[tile.letter] || 0) + 1;
            }
        }

        var words = requiredLen ? (this._dictByLen[requiredLen] || []) : WordDict;
        for (var i = 0; i < words.length; i++)
        {
            if (this._WordDeficit(words[i], counts) <= jokers)
                return true;
        }
        return false;
    }

    _WordDeficit(word, counts)
    {
        var deficit = 0;
        var need = globalThis.WordDictNeeds ? WordDictNeeds[word] : null;
        if (need)
        {
            for (var ch in need)
            {
                var lack = need[ch] - (counts[ch] || 0);
                if (lack > 0)
                    deficit += lack;
            }
            return deficit;
        }

        var local = {};
        for (var i = 0; i < word.length; i++)
        {
            var ch = word[i];
            local[ch] = (local[ch] || 0) + 1;
            if (local[ch] > (counts[ch] || 0))
                deficit++;
        }
        return deficit;
    }

    _EnsureTasksAchievable()
    {
        if (this._state != "playing")
            return [];

        var repaired = [];

        // полный перебор словаря дорогой — считаем не более одного раза
        var fullBest;
        var fullBestComputed = false;
        var self = this;
        var getBest = function()
        {
            if (!fullBestComputed)
            {
                fullBest = self.FindBestWord();
                fullBestComputed = true;
            }
            return fullBest;
        };

        // на поле вообще нет ни одного слова — подсеять случайное короткое
        if (!this._AnyWordExists())
            this._PlantMissingLetters(this._RandomDictWord(4), repaired);

        for (var i = 0; i < this._tasks.length; i++)
        {
            var t = this._tasks[i];
            if (t.done)
                continue;

            if (t.type == "word" && !this._CanAssembleWord(t.word))
                this._PlantMissingLetters(t.word, repaired);
            else if (t.type == "length" && !this._AnyWordExists(t.len))
                this._PlantMissingLetters(this._RandomDictWord(t.len), repaired);
            else if (t.type == "powerup")
            {
                var len = WordFallConfig.powerupLengths[t.kind] || 5;
                var achievable = this._AnyWordExists(len) || (t.kind == "wand" && this._AnyWordExists(8));
                if (!achievable)
                    this._PlantMissingLetters(this._RandomDictWord(len), repaired);
            }
            else if (t.type == "wordScore")
            {
                var best = getBest();
                if (!best || Math.ceil(best.value) < t.score)
                    this._PlantMissingLetters(this._ExpensiveDictWord(), repaired);
            }
        }
        return repaired;
    }

    // Подсказка: самое дорогое слово словаря, собираемое из букв поля
    // (выбор свободный — важен только мультинабор букв). Быстрый отсев по
    // счётчикам, затем жадный подбор плиток (дорогие первыми).
    // requiredLen ограничивает длину слова (для задач и проверок выполнимости).
    FindBestWord(requiredLen)
    {
        var pool = [];
        for (var c = 0; c < this._cols; c++)
        {
            for (var r = 0; r < this._rows; r++)
            {
                var tile = this._grid[c][r];
                if (tile.ice == 0)
                    pool.push({ c: c, r: r, tile: tile });
            }
        }

        // дорогие плитки первыми — жадный выбор максимизирует очки
        pool.sort(function(a, b) {
            var av = a.tile.joker ? 0 : a.tile.value * (a.tile.doubled ? 2 : 1);
            var bv = b.tile.joker ? 0 : b.tile.value * (b.tile.doubled ? 2 : 1);
            return bv - av;
        });

        var poolCounts = {};
        var poolJokers = 0;
        for (var p = 0; p < pool.length; p++)
        {
            if (pool[p].tile.joker)
                poolJokers++;
            else
                poolCounts[pool[p].tile.letter] = (poolCounts[pool[p].tile.letter] || 0) + 1;
        }

        // счётчики букв каждого слова считаются один раз на процесс
        if (!globalThis.WordDictNeeds)
        {
            globalThis.WordDictNeeds = {};
            for (var i = 0; i < WordDict.length; i++)
            {
                var w = WordDict[i];
                var n = {};
                for (var li = 0; li < w.length; li++)
                    n[w[li]] = (n[w[li]] || 0) + 1;
                WordDictNeeds[w] = n;
            }
        }

        var words = requiredLen ? (this._dictByLen[requiredLen] || []) : WordDict;

        var best = null;
        for (var i = 0; i < words.length; i++)
        {
            var word = words[i];

            var need = WordDictNeeds[word];
            var deficit = 0;
            for (var ch in need)
            {
                var lack = need[ch] - (poolCounts[ch] || 0);
                if (lack > 0)
                    deficit += lack;
            }
            if (deficit > poolJokers)
                continue;

            var used = [];
            var okWord = true;
            for (var li = 0; li < word.length && okWord; li++)
            {
                var found = -1;
                for (var p = 0; p < pool.length; p++)
                {
                    if (used.indexOf(p) >= 0)
                        continue;
                    if (!pool[p].tile.joker && pool[p].tile.letter == word[li])
                    {
                        found = p;
                        break;
                    }
                }
                if (found < 0)
                {
                    // добираем джокером
                    for (var p = 0; p < pool.length; p++)
                    {
                        if (used.indexOf(p) < 0 && pool[p].tile.joker)
                        {
                            found = p;
                            break;
                        }
                    }
                }
                if (found < 0)
                    okWord = false;
                else
                    used.push(found);
            }

            if (!okWord)
                continue;

            var sum = 0;
            for (var u = 0; u < used.length; u++)
            {
                var tile = pool[used[u]].tile;
                sum += tile.joker ? 0 : tile.value * (tile.doubled ? 2 : 1);
            }
            var value = sum * this.LengthMultiplier(word.length);
            if (!best || value > best.value)
            {
                best = {
                    value: value, word: word,
                    cells: used.map(function(u) { return { c: pool[u].c, r: pool[u].r }; })
                };
            }
        }
        return best;
    }

    UseHint()
    {
        if (this._state != "playing" || this._charges[2] <= 0)
            return { ok: false };

        var best = this.FindBestWord();
        if (!best)
            return { ok: false, reason: "no_word" };

        this._charges[2]--;
        this._selected = best.cells.slice();
        return { ok: true, word: best.word, cells: best.cells, value: best.value };
    }

    // Джокер: буква превращается в «?» (любая буква), номинал 0
    UseJoker(c, r)
    {
        if (this._state != "playing" || this._charges[3] <= 0)
            return { ok: false };

        var tile = this._grid[c][r];
        if (tile.ice > 0 || tile.joker)
            return { ok: false };

        this._charges[3]--;
        tile.joker = true;
        tile.value = 0;
        return { ok: true };
    }

    // Удвоитель: номинал буквы ×2
    UseDoubler(c, r)
    {
        if (this._state != "playing" || this._charges[4] <= 0)
            return { ok: false };

        var tile = this._grid[c][r];
        if (tile.ice > 0 || tile.joker || tile.doubled)
            return { ok: false };

        this._charges[4]--;
        tile.doubled = true;
        return { ok: true };
    }

    // --- отладка/тесты ---

    DebugSetTile(c, r, letter)
    {
        this._grid[c][r] = this._MakeTile(letter);
    }

    DebugCompleteTasks()
    {
        for (var i = 0; i < this._tasks.length; i++)
        {
            this._tasks[i].progress = this._tasks[i].count;
            this._tasks[i].done = true;
        }
    }
};

// ---------------------------------------------------------------------------
// Вью-контроллер: находит виджеты, вешает onClick, синхронизирует модель с
// отображением и анимирует падение плиток.
// ---------------------------------------------------------------------------
WordFallGame = class WordFallGame extends o2.Component
{
    constructor()
    {
        super();
        this._model = null;
        this._root = null;
        this._tiles = null;
        this._widgets = {};
        this._levelIndex = 0;
        this._boosterMode = null;   // null | "hammer" | "joker" | "doubler"
        this._fallAnims = [];       // { c, r, offset }
        this._flights = [];         // перелёты букв в панель слова
        this._gainTimer = 0;
        this._wordFlashTimer = 0;

        this._cell = 68;
        this._tileSize = 64;
        this._boardX = 0;
        this._boardY = -20;

        this._slotSize = 40;
        this._slotGap = 4;
        this._wordX = -82;      // центр зоны плашек в лотке
        this._wordY = 295;
        this._wordAreaWidth = 282;

        this._barX = -100;   // прогресс-бар очков
        this._barY = 363;
        this._barWidth = 274;
        this._barHeight = 30;
    }

    OnStart()
    {
        try
        {
            globalThis.WordFall_instance = this; // доступ из тестов

            var seed = (typeof WORDFALL_SEED !== "undefined") ? WORDFALL_SEED : (Date.now() & 0xffffff);
            this._model = new WordModel(seed);
            this._model.NewGame(this._LevelConfig());

            this._FindWidgets();
            this._BindClicks();
            this.SyncAll();
        }
        catch (e)
        {
            print("WordFall OnStart failed: " + e + "\n" + e.stack);
            throw e;
        }
    }

    // --- поиск и кэширование виджетов ---

    _LevelConfig() { return WordFallLevels.Get(this._levelIndex); }

    _IsLastLevel() { return this._levelIndex >= WordFallConfig.levelCount - 1; }

    // Сиблинги актора Game достаются через относительные пути ".." — GetParent()
    // возвращает WeakRef, не пригодный для вызова методов из JS
    _Find(path) { return this._actor.GetChild("../" + path); }

    _FindWidgets()
    {
        this._tiles = [];
        for (var c = 0; c < WordFallConfig.cols; c++)
        {
            this._tiles[c] = [];
            for (var r = 0; r < WordFallConfig.rows; r++)
            {
                var btn = this._Find("Board/Tile_" + c + "_" + r);
                this._tiles[c][r] = {
                    btn: btn,
                    letter: btn.GetLayer("letter").drawable,
                    points: btn.GetLayer("points").drawable,
                    sel: btn.GetLayer("sel"),
                    ice: btn.GetLayer("ice"),
                    bomb: btn.GetLayer("bomb"),
                    rocket: btn.GetLayer("rocket"),
                    wand: btn.GetLayer("wand")
                };
            }
        }

        this._widgets.scoreLabel = this._Find("Hud/ScoreLabel");
        this._widgets.movesLabel = this._Find("Hud/MovesLabel");
        this._widgets.levelLabel = this._Find("Hud/LevelLabel");
        this._widgets.barFill = this._Find("Hud/BarFill");
        this._widgets.gainLabel = this._Find("WordPanel/GainLabel");
        this._widgets.acceptBtn = this._Find("WordPanel/AcceptBtn");
        this._widgets.clearBtn = this._Find("WordPanel/ClearBtn");

        this._widgets.slots = [];
        for (var i = 0; i < 8; i++)
        {
            var slot = this._Find("WordPanel/Slot" + i);
            this._widgets.slots.push({
                widget: slot,
                letter: slot.GetLayer("letter").drawable,
                points: slot.GetLayer("points").drawable
            });
        }

        this._widgets.flyers = [];
        for (var i = 0; i < 4; i++)
        {
            var flyer = this._Find("WordPanel/Flyer" + i);
            this._widgets.flyers.push({
                widget: flyer,
                letter: flyer.GetLayer("letter").drawable,
                points: flyer.GetLayer("points").drawable,
                busy: false
            });
        }
        this._widgets.modeLabel = this._Find("Boosters/ModeLabel");
        this._widgets.popup = this._Find("Popup");
        this._widgets.popupTitle = this._Find("Popup/Title");
        this._widgets.popupScore = this._Find("Popup/ScoreLine");
        this._widgets.restartBtn = this._Find("Popup/RestartBtn");
        this._widgets.restartCaption = this._widgets.restartBtn.GetLayer("caption").drawable;

        this._widgets.taskLabels = [];
        for (var i = 0; i < 5; i++)
            this._widgets.taskLabels.push(this._Find("Tasks/Task" + i));

        this._widgets.boosterBtns = [];
        this._widgets.chargeLabels = [];
        for (var i = 0; i < 5; i++)
        {
            this._widgets.boosterBtns.push(this._Find("Boosters/Booster" + i));
            this._widgets.chargeLabels.push(this._Find("Boosters/Charge" + i));
        }
    }

    _BindClicks()
    {
        var self = this;

        for (var c = 0; c < WordFallConfig.cols; c++)
        {
            for (var r = 0; r < WordFallConfig.rows; r++)
            {
                (function(cc, rr) {
                    self._tiles[cc][rr].btn.onClick = function() { self.OnTileClick(cc, rr); };
                })(c, r);
            }
        }

        this._widgets.acceptBtn.onClick = function() { self.OnAccept(); };
        this._widgets.clearBtn.onClick = function() { self.OnClear(); };
        this._widgets.restartBtn.onClick = function() { self.OnRestart(); };

        var modes = ["hammer", "shuffle", "hint", "joker", "doubler"];
        for (var i = 0; i < 5; i++)
        {
            (function(idx) {
                self._widgets.boosterBtns[idx].onClick = function() { self.OnBooster(idx, modes[idx]); };
            })(i);
        }
    }

    // --- обработчики ---

    OnTileClick(c, r)
    {
        var model = this._model;
        if (model.GetState() != "playing")
            return;

        if (this._boosterMode)
        {
            var mode = this._boosterMode;
            this._boosterMode = null;
            this._CancelFlights();

            var result = mode == "hammer" ? model.UseHammer(c, r)
                       : mode == "joker" ? model.UseJoker(c, r)
                       : model.UseDoubler(c, r);

            if (result.ok && result.moved)
                this._StartFallAnims(result.moved, result.spawned);

            this.SyncAll();

            // молоток может разбить последний лёд и этим выиграть уровень
            if (model.GetState() != "playing")
                this._ShowPopup(model.GetState() == "win");
            return;
        }

        var result = model.ToggleSelect(c, r);
        if (result == "added")
            this._StartFlight(c, r, model.GetSelected().length - 1);
        this.SyncSelection();
        this.SyncWord();
    }

    OnAccept()
    {
        var model = this._model;
        var result = model.AcceptWord();
        if (!result.ok)
        {
            if (result.reason == "invalid")
                this._wordFlashTimer = 0.7;
            this.SyncWord();
            return;
        }

        this._CancelFlights();
        this._StartFallAnims(result.moved, result.spawned);

        this._widgets.gainLabel.SetText("+" + result.gain);
        this._gainTimer = 1.6;

        this.SyncAll();

        if (result.state != "playing")
            this._ShowPopup(result.state == "win");
    }

    OnClear()
    {
        this._model.ClearSelection();
        this._boosterMode = null;
        this._CancelFlights();
        this.SyncAll();
    }

    OnBooster(index, mode)
    {
        var model = this._model;
        if (model.GetState() != "playing")
            return;

        if (this._boosterMode == mode)
        {
            this._boosterMode = null; // повторный клик — отмена прицела
            this.SyncHud();
            return;
        }

        if (model.GetCharges(index) <= 0)
            return;

        if (mode == "shuffle")
        {
            this._CancelFlights();
            model.UseShuffle();
            this.SyncAll();
        }
        else if (mode == "hint")
        {
            this._CancelFlights();
            model.UseHint();
            this.SyncAll();
        }
        else
        {
            this._boosterMode = mode;
            this.SyncHud();
        }
    }

    // Кнопка попапа: после победы — следующий уровень (после последнего — первый),
    // после поражения — рестарт текущего
    OnRestart()
    {
        if (this._model.GetState() == "win")
            this._levelIndex = this._IsLastLevel() ? 0 : this._levelIndex + 1;

        this._model.NewGame(this._LevelConfig());
        this._boosterMode = null;
        this._fallAnims = [];
        this._CancelFlights();
        this._widgets.popup.SetEnabled(false);
        this.SyncAll();
    }

    // --- синхронизация модель → вью ---

    SyncAll()
    {
        this.SyncBoard();
        this.SyncSelection();
        this.SyncWord();
        this.SyncHud();
    }

    SyncTile(c, r)
    {
        var tile = this._model.GetTile(c, r);
        var view = this._tiles[c][r];

        view.letter.text = tile.joker ? "?" : tile.letter;
        view.letter.color = tile.joker ? new Color4(160, 90, 200, 255)
                          : tile.ice > 0 ? new Color4(44, 106, 158, 255)   // буква на льду синеет, как в концепте
                          : new Color4(107, 66, 24, 255);

        if (tile.joker)
            view.points.text = "";
        else
            view.points.text = "" + tile.value * (tile.doubled ? 2 : 1);
        view.points.color = tile.doubled ? new Color4(215, 150, 20, 255)
                          : tile.ice > 0 ? new Color4(64, 124, 172, 255)
                          : new Color4(138, 90, 42, 255);

        view.ice.SetEnabled(tile.ice > 0);
        view.bomb.SetEnabled(tile.powerup == "bomb");
        view.rocket.SetEnabled(tile.powerup == "rocket");
        view.wand.SetEnabled(tile.powerup == "wand");
    }

    SyncBoard()
    {
        for (var c = 0; c < WordFallConfig.cols; c++)
        {
            for (var r = 0; r < WordFallConfig.rows; r++)
                this.SyncTile(c, r);
        }
    }

    SyncSelection()
    {
        var selected = this._model.GetSelected();
        for (var c = 0; c < WordFallConfig.cols; c++)
        {
            for (var r = 0; r < WordFallConfig.rows; r++)
            {
                var isSel = selected.some(function(s) { return s.c == c && s.r == r; });
                this._tiles[c][r].sel.SetEnabled(isSel);
            }
        }
    }

    // --- слово из плиток-слотов ---

    _SlotPos(index, count)
    {
        // длинное слово ужимается, чтобы не вылезать из лотка
        var step = this._slotSize + this._slotGap;
        if (count > 1)
            step = Math.min(step, (this._wordAreaWidth - this._slotSize) / (count - 1));
        var total = step*(count - 1) + this._slotSize;
        return new Vec2(this._wordX - total*0.5 + this._slotSize*0.5 + index*step, this._wordY);
    }

    _SetWidgetRect(widget, x, y, size)
    {
        var half = size*0.5;
        var layout = widget.GetLayout();
        layout.SetOffsetMin(new Vec2(x - half, y - half));
        layout.SetOffsetMax(new Vec2(x + half, y + half));
    }

    _FillLetterTile(view, tile)
    {
        view.letter.text = tile.joker ? "?" : tile.letter;
        view.points.text = tile.joker ? "" : ("" + tile.value * (tile.doubled ? 2 : 1));
    }

    SyncWord()
    {
        var model = this._model;
        var selected = model.GetSelected();
        var word = model.CurrentWord();
        var valid = word.length >= 2 && model.IsWordInDict(word);
        var count = selected.length;

        var letterColor = this._wordFlashTimer > 0 ? new Color4(200, 60, 40, 255)
                        : valid ? new Color4(56, 142, 60, 255) : new Color4(107, 66, 24, 255);

        for (var i = 0; i < this._widgets.slots.length; i++)
        {
            var slot = this._widgets.slots[i];
            if (i >= count)
            {
                slot.widget.SetEnabled(false);
                continue;
            }

            var tile = model.GetTile(selected[i].c, selected[i].r);
            this._FillLetterTile(slot, tile);
            slot.letter.color = letterColor;

            var pos = this._SlotPos(i, count);
            this._SetWidgetRect(slot.widget, pos.x, pos.y, this._slotSize);

            // пока буква летит в этот слот — слот скрыт
            var flying = this._flights.some(function(f) { return f.slot == i; });
            slot.widget.SetEnabled(!flying);
        }
    }

    // --- перелёт буквы с плитки в панель слова (безье с изингом) ---

    _StartFlight(c, r, slotIndex)
    {
        var flyer = null;
        for (var i = 0; i < this._widgets.flyers.length; i++)
        {
            if (!this._widgets.flyers[i].busy)
            {
                flyer = this._widgets.flyers[i];
                break;
            }
        }
        if (!flyer)
            return; // все флаеры заняты — слот просто появится

        this._FillLetterTile(flyer, this._model.GetTile(c, r));
        flyer.letter.color = new Color4(107, 66, 24, 255);
        flyer.busy = true;
        flyer.widget.SetEnabled(true);

        var from = this._TilePos(c, r);
        this._SetWidgetRect(flyer.widget, from.x, from.y, this._tileSize);
        this._flights.push({ flyer: flyer, slot: slotIndex, t: 0, dur: 0.38, from: from });
    }

    _FinishFlight(flight)
    {
        flight.flyer.busy = false;
        flight.flyer.widget.SetEnabled(false);
    }

    _CancelFlights()
    {
        for (var i = 0; i < this._flights.length; i++)
            this._FinishFlight(this._flights[i]);
        this._flights = [];
    }

    _UpdateFlights(dt)
    {
        if (this._flights.length == 0)
            return;

        var count = this._model.GetSelected().length;
        var alive = [];
        for (var i = 0; i < this._flights.length; i++)
        {
            var f = this._flights[i];
            f.t += dt / f.dur;

            // буква снята с выбора, пока летела — гасим перелёт
            if (f.slot >= count)
            {
                this._FinishFlight(f);
                continue;
            }

            var to = this._SlotPos(f.slot, count);
            var t = Math.min(f.t, 1);
            var e = t*t*(3 - 2*t); // smoothstep

            // квадратичное безье: контрольная точка выше и сбоку от середины
            var cx = (f.from.x + to.x)*0.5 + (to.x - f.from.x)*0.18;
            var cy = Math.max(f.from.y, to.y) + 95;
            var inv = 1 - e;
            var x = inv*inv*f.from.x + 2*inv*e*cx + e*e*to.x;
            var y = inv*inv*f.from.y + 2*inv*e*cy + e*e*to.y;

            // размер: от плитки к слоту, с лёгким «вспуханием» по дороге
            var size = this._tileSize + (this._slotSize - this._tileSize)*e + 10*Math.sin(Math.PI*e);
            this._SetWidgetRect(f.flyer.widget, x, y, size);

            if (f.t >= 1)
                this._FinishFlight(f);
            else
                alive.push(f);
        }

        var landed = alive.length != this._flights.length;
        this._flights = alive;
        if (landed)
            this.SyncWord(); // открыть слоты приземлившихся букв
    }

    _TaskText(task)
    {
        if (task.type == "word")
            return "Слово " + task.word;
        if (task.type == "length")
            return "Слова из " + task.len + " букв: " + task.progress + "/" + task.count;
        if (task.type == "powerup")
        {
            var names = { bomb: "Бомба", rocket: "Ракета", wand: "Палочка" };
            return (names[task.kind] || "Бонус") + ": " + task.progress + "/" + task.count;
        }
        if (task.type == "anyWords")
            return "Собрать слов: " + task.progress + "/" + task.count;
        if (task.type == "wordScore")
            return "Слово на " + task.score + "+ очков";
        return "Разбить весь лёд";
    }

    SyncTasks()
    {
        var tasks = this._model.GetTasks();
        for (var i = 0; i < this._widgets.taskLabels.length; i++)
        {
            var label = this._widgets.taskLabels[i];
            if (i >= tasks.length)
            {
                label.SetText("");
                continue;
            }

            var task = tasks[i];
            label.SetText((task.done ? "+ " : "- ") + this._TaskText(task));
            label.SetColor(task.done ? new Color4(60, 150, 60, 255) : new Color4(92, 57, 26, 255));
        }
    }

    SyncHud()
    {
        var model = this._model;
        this._widgets.scoreLabel.SetText(model.GetScore() + "/" + model.GetTarget());
        this._widgets.movesLabel.SetText("Ходы: " + model.GetMovesLeft());
        this._widgets.levelLabel.SetText("Уровень " + (this._levelIndex + 1));
        this.SyncTasks();

        // заливка прогресс-бара очков
        var progress = Math.max(0, Math.min(1, model.GetScore() / model.GetTarget()));
        var fill = this._widgets.barFill;
        if (progress <= 0)
            fill.SetEnabled(false);
        else
        {
            fill.SetEnabled(true);
            var width = Math.max(34, this._barWidth * progress);
            var left = this._barX - this._barWidth*0.5;
            var layout = fill.GetLayout();
            layout.SetOffsetMin(new Vec2(left, this._barY - this._barHeight*0.5));
            layout.SetOffsetMax(new Vec2(left + width, this._barY + this._barHeight*0.5));
        }

        for (var i = 0; i < 5; i++)
            this._widgets.chargeLabels[i].SetText("" + model.GetCharges(i));

        var modeTexts = {
            hammer: "Молоток: кликните плитку",
            joker: "Джокер: кликните плитку",
            doubler: "Удвоитель: кликните плитку"
        };
        this._widgets.modeLabel.SetText(this._boosterMode ? modeTexts[this._boosterMode] : "");

        if (this._gainTimer <= 0)
            this._widgets.gainLabel.SetText("");
    }

    _ShowPopup(win)
    {
        var last = this._IsLastLevel();
        this._widgets.popupTitle.SetText(win ? (last ? "ИГРА ПРОЙДЕНА!" : "УРОВЕНЬ ПРОЙДЕН!") : "ПОРАЖЕНИЕ");
        this._widgets.popupScore.SetText("Очки: " + this._model.GetScore());
        this._widgets.restartCaption.text = win ? (last ? "СНАЧАЛА" : "ДАЛЬШЕ") : "ЕЩЁ РАЗ";
        this._widgets.popup.SetEnabled(true);
    }

    // --- анимация падения ---

    _TilePos(c, r)
    {
        return new Vec2(this._boardX + (c - 3)*this._cell,
                        this._boardY + (r - 3.5)*this._cell);
    }

    _SetTileRect(c, r, extraY)
    {
        var pos = this._TilePos(c, r);
        var half = this._tileSize * 0.5;
        var layout = this._tiles[c][r].btn.GetLayout();
        layout.SetOffsetMin(new Vec2(pos.x - half, pos.y + extraY - half));
        layout.SetOffsetMax(new Vec2(pos.x + half, pos.y + extraY + half));
    }

    _StartFallAnims(moved, spawned)
    {
        // старые анимации сбрасываем в конечное положение
        for (var i = 0; i < this._fallAnims.length; i++)
            this._SetTileRect(this._fallAnims[i].c, this._fallAnims[i].r, 0);
        this._fallAnims = [];

        for (var i = 0; i < moved.length; i++)
        {
            var m = moved[i];
            this._fallAnims.push({ c: m.c, r: m.toR, offset: (m.fromR - m.toR) * this._cell });
        }
        for (var i = 0; i < spawned.length; i++)
        {
            var s = spawned[i];
            this._fallAnims.push({ c: s.c, r: s.r, offset: (WordFallConfig.rows - s.r) * this._cell + 60 });
        }

        for (var i = 0; i < this._fallAnims.length; i++)
        {
            var a = this._fallAnims[i];
            this._SetTileRect(a.c, a.r, a.offset);
        }
    }

    Update(dt)
    {
        this._UpdateFlights(dt);

        if (this._fallAnims.length > 0)
        {
            var speed = 700;
            var alive = [];
            for (var i = 0; i < this._fallAnims.length; i++)
            {
                var a = this._fallAnims[i];
                a.offset -= speed * dt;
                if (a.offset <= 0)
                    this._SetTileRect(a.c, a.r, 0);
                else
                {
                    this._SetTileRect(a.c, a.r, a.offset);
                    alive.push(a);
                }
            }
            this._fallAnims = alive;
        }

        if (this._gainTimer > 0)
        {
            this._gainTimer -= dt;
            if (this._gainTimer <= 0)
                this._widgets.gainLabel.SetText("");
        }

        if (this._wordFlashTimer > 0)
        {
            this._wordFlashTimer -= dt;
            if (this._wordFlashTimer <= 0)
                this.SyncWord();
        }
    }

    // --- отладка/тесты ---

    DebugSetTile(c, r, letter)
    {
        this._model.DebugSetTile(c, r, letter);
        this.SyncTile(c, r);
    }

    DebugGetModel() { return this._model; }
};
